selector_to_html = {"a[href=\"nvidia.html#compile-paddle-with-flagcx\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Compile paddle with FlagCX<a class=\"headerlink\" href=\"#compile-paddle-with-flagcx\" title=\"Link to this heading\">#</a></h2><p>Please follow the following commands:</p>", "a[href=\"#training-models-with-paddle-and-flagcx\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Training Models with Paddle and FlagCX<a class=\"headerlink\" href=\"#training-models-with-paddle-and-flagcx\" title=\"Link to this heading\">#</a></h1><p>FlagCX is now fully integrated into Paddle as an <strong>optional high-performance communication backend</strong>. This integration enables efficient distributed training on multiple hardware platforms, including support for <strong>heterogeneous training</strong> on Nvidia and Iluvatar GPUs.</p><p>Use the guides below to quickly get started with training models using Paddle + FlagCX.</p>", "a[href=\"kunlun.html#environment-setup\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Environment setup<a class=\"headerlink\" href=\"#environment-setup\" title=\"Link to this heading\">#</a></h2>", "a[href=\"nvidia.html#environment-setup\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Environment setup<a class=\"headerlink\" href=\"#environment-setup\" title=\"Link to this heading\">#</a></h2>", "a[href=\"nvidia-iluvatar-hetero-train.html#environment-setup\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Environment setup<a class=\"headerlink\" href=\"#environment-setup\" title=\"Link to this heading\">#</a></h2><p>Please refer to <a class=\"reference internal\" href=\"nvidia.html\"><span class=\"std std-doc\">NVIDIA</span></a> and <a class=\"reference internal\" href=\"iluvatar.html\"><span class=\"std std-doc\">Iluvatar</span></a> for environment setup and compiling Paddle with FlagCX on Nvidia and Iluvatar machines.</p>", "a[href=\"nvidia-iluvatar-hetero-train.html#training-on-heterogeneous-ai-accelerators-nvidia-gpu-iluvatar-gpu\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Training on heterogeneous ai accelerators (nvidia GPU + iluvatar GPU)<a class=\"headerlink\" href=\"#training-on-heterogeneous-ai-accelerators-nvidia-gpu-iluvatar-gpu\" title=\"Link to this heading\">#</a></h2><p>We now support training ERNIE4.5 using Nvidia GPUs and Iluvatar GPUs together. Please refer to the following steps to get started</p>", "a[href=\"iluvatar.html#train-model-using-paddle-flagcx\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Train model using paddle + FlagCX<a class=\"headerlink\" href=\"#train-model-using-paddle-flagcx\" title=\"Link to this heading\">#</a></h2><p>We now support training ERNIE4.5 on Iluvatar machines using Paddle + FlagCX. Please refer to the following steps to get started</p>", "a[href=\"kunlun.html#train-model-using-paddle-flagcx\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Train model using paddle + FlagCX<a class=\"headerlink\" href=\"#train-model-using-paddle-flagcx\" title=\"Link to this heading\">#</a></h2><p>We now support training GPT3 on XPU machines using Paddle + FlagCX. Please refer to the following steps to get started</p>", "a[href=\"iluvatar.html#compile-paddle-with-flagcx\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Compile paddle with FlagCX<a class=\"headerlink\" href=\"#compile-paddle-with-flagcx\" title=\"Link to this heading\">#</a></h2><p><strong>Note</strong>: To build Paddle with FlagCX on Iluvatar machines, we need to ensure that FlagCX is built before building Paddle</p>", "a[href=\"kunlun.html#compile-paddle-with-flagcx\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Compile paddle with FlagCX<a class=\"headerlink\" href=\"#compile-paddle-with-flagcx\" title=\"Link to this heading\">#</a></h2><p>Please follow the following commands</p>", "a[href=\"iluvatar.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Guide for using paddle with FlagCX on iluvatar machines<a class=\"headerlink\" href=\"#guide-for-using-paddle-with-flagcx-on-iluvatar-machines\" title=\"Link to this heading\">#</a></h1><h2>Environment setup<a class=\"headerlink\" href=\"#environment-setup\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#homogeneous-training\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Homogeneous training<a class=\"headerlink\" href=\"#homogeneous-training\" title=\"Link to this heading\">#</a></h2><p>Train on a single type of hardware platform:</p>", "a[href=\"kunlun.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Guide for using paddle with FlagCX on XPU machines<a class=\"headerlink\" href=\"#guide-for-using-paddle-with-flagcx-on-xpu-machines\" title=\"Link to this heading\">#</a></h1><h2>Environment setup<a class=\"headerlink\" href=\"#environment-setup\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#heterogeneous-training\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Heterogeneous training<a class=\"headerlink\" href=\"#heterogeneous-training\" title=\"Link to this heading\">#</a></h2><p>Train across <strong>different hardware platforms</strong> simultaneously:</p>", "a[href=\"nvidia.html#train-model-using-paddle-flagcx\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Train model using paddle + FlagCX<a class=\"headerlink\" href=\"#train-model-using-paddle-flagcx\" title=\"Link to this heading\">#</a></h2><p>We now support training GPT3 on NVIDIA GPU environment using Paddle + FlagCX. Please refer to the following steps to get started.</p>", "a[href=\"nvidia.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Guide for using paddle with FlagCX on nvidia GPU environment<a class=\"headerlink\" href=\"#guide-for-using-paddle-with-flagcx-on-nvidia-gpu-environment\" title=\"Link to this heading\">#</a></h1><h2>Environment setup<a class=\"headerlink\" href=\"#environment-setup\" title=\"Link to this heading\">#</a></h2>", "a[href=\"nvidia-iluvatar-hetero-train.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Guide for training on nvidia and iluvatar GPUs<a class=\"headerlink\" href=\"#guide-for-training-on-nvidia-and-iluvatar-gpus\" title=\"Link to this heading\">#</a></h1><h2>Environment setup<a class=\"headerlink\" href=\"#environment-setup\" title=\"Link to this heading\">#</a></h2><p>Please refer to <a class=\"reference internal\" href=\"nvidia.html\"><span class=\"std std-doc\">NVIDIA</span></a> and <a class=\"reference internal\" href=\"iluvatar.html\"><span class=\"std std-doc\">Iluvatar</span></a> for environment setup and compiling Paddle with FlagCX on Nvidia and Iluvatar machines.</p>", "a[href=\"iluvatar.html#environment-setup\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Environment setup<a class=\"headerlink\" href=\"#environment-setup\" title=\"Link to this heading\">#</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
